/** Select real H1/H2 headings while preserving headings quoted inside fenced examples. */
function headings(value) {
  const found = [];
  let offset = 0, fence = null;
  for (const line of value.split('\n')) {
    const marker = line.match(/^ {0,3}(`{3,}|~{3,})(.*)$/);
